FUNCTION_BLOCK FB_FCC_RiserTemperatureControl
VAR_INPUT
    bSystemEnable           : BOOL;     (* System master enable *)
    bEmergencyShutdown      : BOOL;     (* ESD ok signal - TRUE means healthy *)
    rRiserTempTRX_1         : REAL;     (* Riser outlet temperature sensor 1 (deg C) *)
    rRiserTempTRX_2         : REAL;     (* Riser outlet temperature sensor 2 (deg C) *)
    rRiserTempTRX_3         : REAL;     (* Riser outlet temperature sensor 3 (deg C) *)
    rRegeneratorTemp        : REAL;     (* Regenerator dense bed temperature (deg C) *)
    rFeedFlowRate           : REAL;     (* Fresh feed flow rate (m3/h) *)
    rReactorPressure        : REAL;     (* Reactor vessel pressure (kPa) *)
    rSlideValvePosFbk       : REAL;     (* Catalyst slide valve position feedback 0-100% *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Control system is armed and ready *)
    rSlideValveCmd          : REAL;     (* Slide valve position command 0-100% *)
    bHighTempAlarm          : BOOL;     (* Riser high temperature deviation alarm *)
    bLowTempAlarm           : BOOL;     (* Riser low temperature deviation alarm *)
    bSensorFault            : BOOL;     (* Temperature transmitter deviation fault *)
    bTripSignal             : BOOL;     (* System trip command to ESD *)
END_VAR
VAR
    iState                  : INT := 0;
    rFilteredRiserTemp      : REAL := 0.0;
    rTempDeviation12        : REAL;
    rTempDeviation23        : REAL;
    rTempDeviation13        : REAL;
    bValidTemp1             : BOOL;
    bValidTemp2             : BOOL;
    bValidTemp3             : BOOL;
    rSetpoint               : REAL := 535.0; (* Optimal cracking temperature *)
    rError                  : REAL;
    rErrorPrev              : REAL := 0.0;
    rIntegral               : REAL := 0.0;
    rDerivative             : REAL := 0.0;
    rKp                     : REAL := 1.25;
    rKi                     : REAL := 0.05;
    rKd                     : REAL := 0.15;
    rPIDOutput              : REAL;
    rMaxTempDev             : REAL := 10.0;
    tStartupDelay           : TON;
    tFaultTimer             : TON;
    bInitialize             : BOOL := TRUE;
END_VAR

(* === SENSOR VALIDATION AND VOTING (2-out-of-3) === *)
rTempDeviation12 := ABS(rRiserTempTRX_1 - rRiserTempTRX_2);
rTempDeviation23 := ABS(rRiserTempTRX_2 - rRiserTempTRX_3);
rTempDeviation13 := ABS(rRiserTempTRX_1 - rRiserTempTRX_3);

bValidTemp1 := (rRiserTempTRX_1 > 400.0 AND rRiserTempTRX_1 < 700.0);
bValidTemp2 := (rRiserTempTRX_2 > 400.0 AND rRiserTempTRX_2 < 700.0);
bValidTemp3 := (rRiserTempTRX_3 > 400.0 AND rRiserTempTRX_3 < 700.0);

bSensorFault := FALSE;

(* Median Selection logic *)
IF bValidTemp1 AND bValidTemp2 AND bValidTemp3 THEN
    IF (rRiserTempTRX_1 >= rRiserTempTRX_2 AND rRiserTempTRX_1 <= rRiserTempTRX_3) OR (rRiserTempTRX_1 >= rRiserTempTRX_3 AND rRiserTempTRX_1 <= rRiserTempTRX_2) THEN
        rFilteredRiserTemp := rRiserTempTRX_1;
    ELSIF (rRiserTempTRX_2 >= rRiserTempTRX_1 AND rRiserTempTRX_2 <= rRiserTempTRX_3) OR (rRiserTempTRX_2 >= rRiserTempTRX_3 AND rRiserTempTRX_2 <= rRiserTempTRX_1) THEN
        rFilteredRiserTemp := rRiserTempTRX_2;
    ELSE
        rFilteredRiserTemp := rRiserTempTRX_3;
    END_IF;
ELSIF bValidTemp1 AND bValidTemp2 THEN
    rFilteredRiserTemp := (rRiserTempTRX_1 + rRiserTempTRX_2) / 2.0;
    bSensorFault := TRUE;
ELSIF bValidTemp2 AND bValidTemp3 THEN
    rFilteredRiserTemp := (rRiserTempTRX_2 + rRiserTempTRX_3) / 2.0;
    bSensorFault := TRUE;
ELSIF bValidTemp1 AND bValidTemp3 THEN
    rFilteredRiserTemp := (rRiserTempTRX_1 + rRiserTempTRX_3) / 2.0;
    bSensorFault := TRUE;
ELSE
    rFilteredRiserTemp := rRiserTempTRX_1; (* Fallback, imminent trip *)
    bTripSignal := TRUE;
END_IF;

(* === MAIN STATE MACHINE === *)
IF NOT bEmergencyShutdown THEN
    bSystemReady := FALSE;
    bTripSignal := TRUE;
    rSlideValveCmd := 0.0; (* Fail closed for catalyst valve *)
    iState := 0;
    rIntegral := 0.0;
    RETURN;
END_IF;

CASE iState OF
    0: (* FAULT / STANDBY *)
        bSystemReady := FALSE;
        rSlideValveCmd := 0.0;
        bHighTempAlarm := FALSE;
        bLowTempAlarm := FALSE;

        IF bSystemEnable AND NOT bTripSignal THEN
            tStartupDelay(IN := TRUE, PT := T#10S);
            IF tStartupDelay.Q THEN
                iState := 10;
                tStartupDelay(IN := FALSE);
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

    10: (* INITIALIZATION & PURGE *)
        bSystemReady := TRUE;
        rSlideValveCmd := 5.0; (* Minimum opening to establish differential pressure *)

        IF rRegeneratorTemp > 650.0 AND rReactorPressure > 150.0 THEN
            iState := 20;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* PID ACTIVE CONTROL *)
        bSystemReady := TRUE;

        rError := rSetpoint - rFilteredRiserTemp;

        (* Anti-windup clamping for integral *)
        IF (rSlideValveCmd < 100.0 AND rError > 0.0) OR (rSlideValveCmd > 0.0 AND rError < 0.0) THEN
            rIntegral := rIntegral + (rError * rKi);
        END_IF;

        rDerivative := (rError - rErrorPrev) * rKd;
        rPIDOutput := (rError * rKp) + rIntegral + rDerivative;

        (* Velocity and Position Limiting *)
        rSlideValveCmd := rPIDOutput;
        IF rSlideValveCmd > 100.0 THEN
            rSlideValveCmd := 100.0;
        ELSIF rSlideValveCmd < 0.0 THEN
            rSlideValveCmd := 0.0;
        END_IF;

        rErrorPrev := rError;

        (* Alarm Generation *)
        IF rFilteredRiserTemp > (rSetpoint + rMaxTempDev) THEN
            bHighTempAlarm := TRUE;
        ELSE
            bHighTempAlarm := FALSE;
        END_IF;

        IF rFilteredRiserTemp < (rSetpoint - rMaxTempDev) THEN
            bLowTempAlarm := TRUE;
        ELSE
            bLowTempAlarm := FALSE;
        END_IF;

        (* Severe deviation trip *)
        IF rFilteredRiserTemp > 560.0 OR rFilteredRiserTemp < 500.0 THEN
            tFaultTimer(IN := TRUE, PT := T#3S);
            IF tFaultTimer.Q THEN
                bTripSignal := TRUE;
                iState := 0;
            END_IF;
        ELSE
            tFaultTimer(IN := FALSE);
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
